// msgText returns the value of a message in one language block, read out of the blob. One index
// computation and one slice: no map, no hash of the message text, no fallback branch.
func msgText(id Msg, block int) string {
	if block < 0 || block >= 2 || int(id) >= 84 {
		return ""
	}
	k := block*84 + int(id)
	return msgBlob[msgOffsets[k]:msgOffsets[k+1]]
}

// MsgLangs returns the shipped languages, in blob order (the source language first).
func MsgLangs() []string { return append([]string(nil), msgLangs[:]...) }

// MsgKey returns the dotted id of a message, for diagnostics and test names.
func MsgKey(id Msg) string {
	keys := MsgKeys()
	if int(id) >= len(keys) {
		return ""
	}
	return keys[id]
}

